//! Color space types and conversions, re-implemented from the behavior of the
//! C++ `ColorSpace` library (black-box port). All arithmetic is done in `f32`
//! to match the original library's `float` precision exactly.

pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

pub struct Hsv {
    pub h: f32,
    pub s: f32,
    pub v: f32,
}

pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

pub struct Yuv {
    pub y: f32,
    pub u: f32,
    pub v: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Rgb {
        Rgb { r, g, b }
    }
}

/// Matches `std::max(a, b)` semantics: `a < b ? b : a`.
fn cpp_max(a: f32, b: f32) -> f32 {
    if a < b {
        b
    } else {
        a
    }
}

/// Matches `std::min(a, b)` semantics: `b < a ? b : a`.
fn cpp_min(a: f32, b: f32) -> f32 {
    if b < a {
        b
    } else {
        a
    }
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: &Rgb) -> Hsl {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(r, cpp_max(g, b));
        let min = cpp_min(r, cpp_min(g, b));
        let l = (max + min) / 2.0;

        let (h, s);
        if max == min {
            h = 0.0;
            s = 0.0;
        } else {
            let d = max - min;
            s = if l > 0.5 {
                d / (2.0 - max - min)
            } else {
                d / (max + min)
            };
            let mut hue = if max == r {
                (g - b) / d + if g < b { 6.0 } else { 0.0 }
            } else if max == g {
                (b - r) / d + 2.0
            } else {
                (r - g) / d + 4.0
            };
            hue *= 60.0;
            h = hue;
        }
        Hsl { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: &Rgb) -> Hsv {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let max = cpp_max(r, cpp_max(g, b));
        let min = cpp_min(r, cpp_min(g, b));
        let v = max;

        let (h, s);
        if max == min {
            h = 0.0;
            s = 0.0;
        } else {
            let d = max - min;
            s = d / max;
            let mut hue = if max == r {
                (g - b) / d + if g < b { 6.0 } else { 0.0 }
            } else if max == g {
                (b - r) / d + 2.0
            } else {
                (r - g) / d + 4.0
            };
            hue *= 60.0;
            h = hue;
        }
        Hsv { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: &Rgb) -> Cmyk {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        let k = 1.0 - cpp_max(r, cpp_max(g, b));
        if k == 1.0 {
            Cmyk {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            }
        } else {
            Cmyk {
                c: (1.0 - r - k) / (1.0 - k),
                m: (1.0 - g - k) / (1.0 - k),
                y: (1.0 - b - k) / (1.0 - k),
                k,
            }
        }
    }

    pub fn rgb_to_yuv(rgb: &Rgb) -> Yuv {
        let (r, g, b) = (rgb.r, rgb.g, rgb.b);
        Yuv {
            y: 0.299 * r + 0.587 * g + 0.114 * b,
            u: -0.147 * r - 0.289 * g + 0.436 * b,
            v: 0.615 * r - 0.515 * g - 0.1 * b,
        }
    }
}

