fn hue_variants(r: f32, g: f32, b: f32) {
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let d = max - min;
    let off = if max == r { if g < b { 6.0f32 } else { 0.0 } } else if max == g { 2.0 } else { 4.0 };
    let base = if max == r { (g - b) / d } else if max == g { (b - r) / d } else { (r - g) / d };
    let a = (base + off) * 60.0;              // A: ((x/d)+off)*60
    let b1 = { let mut h = base + off; h /= 6.0; h *= 360.0; h }; // B: /6 then *360
    // double-internal variant
    let rd = r as f64; let gd = g as f64; let bd = b as f64;
    let maxd = rd.max(gd).max(bd); let mind = rd.min(gd).min(bd);
    let dd = maxd - mind;
    let offd = off as f64;
    let based = if max == r { (gd - bd) / dd } else if max == g { (bd - rd) / dd } else { (rd - gd) / dd };
    let e = (based + offd) * 60.0;            // E: double internal
    let f = ((based + offd) * 60.0) as f32;   // F: double internal, stored float
    println!("A={a:.9} B={b1:.9} E={e:.9} F={f:.9}");
}
fn main() {
